import React, { useState } from "react";
import axios from "axios";
import "./Payment.css";

const Payment = () => {
  const [paymentDetails, setPaymentDetails] = useState({
    checkInDate: "",
    checkOutDate: "",
    name: "",
    email: "",
    phoneNumber: "",
  });

  const [loading, setLoading] = useState(false);
  const [responseMessage, setResponseMessage] = useState("");

  const handleChange = (e) => {
    const { name, value } = e.target;
    setPaymentDetails({ ...paymentDetails, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setResponseMessage("");
    try {
      const response = await axios.post("http://localhost:5000/api/payment", paymentDetails);
      console.log(response.data);
      setPaymentDetails({
        checkInDate: "",
        checkOutDate: "",
        name: "",
        email: "",
        phoneNumber: "",
      });
      setResponseMessage("Booking details sent successfully!");
    } catch (error) {
      console.error("Error sending booking details", error);
      setResponseMessage("Failed to send booking details. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="payment-form-container">
      <h2 className="payment-title">Booking Details</h2>
      <form onSubmit={handleSubmit} className="payment-form">
        <input
          type="text"
          name="name"
          value={paymentDetails.name}
          onChange={handleChange}
          placeholder="Name"
          required
          className="payment-input"
        />
        <input
          type="email"
          name="email"
          value={paymentDetails.email}
          onChange={handleChange}
          placeholder="Email"
          required
          className="payment-input"
        />
        <input
          type="tel"
          name="phoneNumber"
          value={paymentDetails.phoneNumber}
          onChange={handleChange}
          placeholder="Phone Number"
          required
          className="payment-input"
        />
        <input
          type="date"
          name="checkInDate"
          label="Check-In Date"  
          value={paymentDetails.checkInDate}
          onChange={handleChange}
          placeholder="Check-In Date"
          required
          className="payment-input"
        />
        <input
          type="date"
          name="checkOutDate"
          label="Check-Out Date"
          value={paymentDetails.checkOutDate}
          onChange={handleChange}
          placeholder="Check-Out Date"
          required
          className="payment-input"
        />
        <button type="submit" className="payment-button" disabled={loading}>
          {loading ? "Sending..." : "Confirm Booking"}
        </button>
      </form>

      {/* Success or Error Message */}
      {responseMessage && (
        <p className={responseMessage.includes("success") ? "success-message" : "error-message"}>
          {responseMessage}
        </p>
      )}
    </div>
  );
};

export default Payment;
